import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Fotoğrafın üzerindeki metin, kontrast yoksa kaybolur. En güzel yazı tipi bile, zeminden ayrılmıyorsa okunamaz.</p>\n<p>Kontrast, yazı tipinden önemlidir. Doğru kontrast, her yazı tipini okunur yapar; yanlış kontrast, en iyi tipi bile bozar.</p>\n<p>Bu yazı, harf ile zemin arasındaki ilişkiyi, fotoğrafı koyulaştırma ve açma yöntemlerini ve küçük ekranlarda test etmeyi anlatıyor.</p>\n<h2 id=\"why-contrast-matters\">Kontrast yazı tipinden neden daha önemlidir?</h2>\n<p>Kontrast yetersizse yazı okunmaz ve mesaj ulaşmaz; okur, okuyamadığı görseli saniyesinde kaydırıp geçer.</p>\n<p>Kontrast, okunabilirliğin temelidir. Yazı tipi stildir; kontrast, görünürlüktür.</p>\n<p>Önce kontrastı düzeltin, sonra yazı tipini seçin. Sıralama, doğru sonucu verir.</p>\n<h2 id=\"text-vs-background\">Metin ve arka plan: merkezi ilişki</h2>\n<p>Metin ile arka plan arasındaki fark büyük olmalıdır. Beyaz yazı koyu zeminde, siyah yazı açık zeminde okunur.</p>\n<p>Fotoğrafta zemin değişir. Bir bölgede koyu, başka bölgede açık olabilir; metni düz alana koyun.</p>\n<p>Zemin düz değilse panel kullanın. Yarı saydam koyu panel, metni her zeminde okunur yapar.</p>\n<h2 id=\"choosing-text-colour\">Kontrast için metin rengi seçmek</h2>\n<p>Metin rengini fotoğrafın tonuna göre belirleyin; koyu karede beyaz, açık karede siyah yazı kontrastı sağlar.</p>\n<p>Marka rengini kullanabilirsiniz. Renk markayı taşır; okunabilirlik önce gelmelidir.</p>\n<p>Kontrastı yalnızca renge dayandırmayın; kırmızı-yeşil farkı, renk körü okurlar için hiç fark yaratmayabilir.</p>\n<h2 id=\"darkening-photo\">Metnin arkasındaki fotoğrafı koyulaştırmak</h2>\n<p>Fotoğrafı koyulaştırmak, beyaz yazıyı okunur yapar. Parlaklığı azaltın ya da koyu katman ekleyin.</p>\n<p>Tüm fotoğrafı koyulaştırmak yerine yalnızca metin alanını koyulaştırın. Fotoğrafın geri kalanı parlak kalır.</p>\n<p>Degrade koyulaştırma kullanın. Alt kısım koyu, üst kısım açık olabilir; metin altta durur.</p>\n<h2 id=\"lightening-photo\">Koyu metnin arkasındaki fotoğrafı açmak</h2>\n<p>Fotoğrafı açmak, siyah yazıyı okunur yapar. Parlaklığı artırın ya da açık katman ekleyin.</p>\n<p>Tüm fotoğrafı açmak yerine yalnızca metin alanını açın. Fotoğrafın geri kalanı koyu kalır.</p>\n<p>Açık panel kullanın. Yarı saydam beyaz panel, metni her zeminde okunur yapar.</p>\n<h2 id=\"overlays-and-panels\">Katmanlar ve arka plan panelleri</h2>\n<p>Fotoğraf üstüne yarı saydam koyu panel koyun; beyaz yazı, panel sayesinde her zeminde okunur kalır.</p>\n<p>Metin panelini aşırı opak tutmayın; kontrastı artırırken fotoğrafın panel arkasından seçilmesi gerekir.</p>\n<p>Kontrast panelinin köşelerini hafifçe yuvarlayın; keskin köşeler, fotoğraf üstü metni sert ve resmî gösterir.</p>\n<h2 id=\"contrast-for-headlines\">Başlıklar için kontrast</h2>\n<p>Başlık büyük yazılır; kontrastı yüksek olmalıdır. Başlık, ilk bakışta okunmalıdır.</p>\n<p>Başlık için kontur kullanın. Beyaz başlığa siyah kontur, her zeminde görünür.</p>\n<p>Başlığı düz alana koyun. Kalabalık zemin, başlığı okunmaz yapar.</p>\n<h2 id=\"contrast-for-captions\">Alt yazılar ve küçük metin için kontrast</h2>\n<p>Küçük metin, daha yüksek kontrast ister. Küçük harfler, düşük kontrastta kaybolur.</p>\n<p>Alt yazı için panel kullanın. Yarı saydam koyu panel, küçük metni okunur yapar.</p>\n<p>Alt yazıyı kısa tutun. Uzun alt yazı, küçük ekranda okunmaz.</p>\n<h2 id=\"testing-readability\">Yayınlamadan önce okunabilirliği test etmek</h2>\n<p>Bilgisayarda net okunan yazı, telefon boyutunda silinebilir; kontrastı telefon ekranında test ederek doğrulayın.</p>\n<p>Kontrastı kontrol ederken görseli küçük boyuta indirin; minik önizlemede kaybolan yazı, akışta da okunmaz.</p>\n<p>Görseli yayına vermeden birkaç kişiye gösterin; dışarıdan bir göz, sizin artık göremediğiniz okunabilirlik hatalarını yakalar.</p>\n<h2 id=\"contrast-for-social\">Sosyal medyada metin için kontrast</h2>\n<p>Sosyal medyada metin büyük ve kontrastlı olmalıdır. Akış hızlı geçer; yazı anında okunmalıdır.</p>\n<p>Başlığı büyük yazın. Küçük yazı, akışta kaybolur.</p>\n<p>Panel kullanın. Yarı saydam koyu panel, metni her zeminde okunur yapar.</p>\n<h2 id=\"contrast-for-slides\">Slayt ve sunumlarda kontrast</h2>\n<p>Slaytlarda kontrast kritiktir. Salonun arka sırasından bile yazı okunmalıdır.</p>\n<p>Beyaz yazıyı koyu zeminde kullanın. Projektörde açık zemin, yazıyı soldurur.</p>\n<p>Yazı tipini büyük tutun. Slayt metni, en az 24 punto olmalıdır.</p>\n<h2 id=\"accessibility\">Erişilebilirlik: herkesin okuyabileceği kontrast</h2>\n<p>Fotoğraf üstü metinde kontrastı hep yüksek tutun; düşük kontrast, az gören okurları yazıdan tamamen koparır.</p>\n<p>Kontrast oranını ölçün. Normal metin için 4.5:1, büyük metin için 3:1 oran gerekir.</p>\n<p>Alternatif metin yazın. Görsel yüklenemezse okur, metinden ne olduğunu anlar.</p>\n<h2 id=\"common-mistakes\">Yaygın kontrast hataları</h2>\n<p>En sık yapılan hata, düşük kontrasttır. Açık fotoğrafta beyaz yazı kaybolur.</p>\n<p>Bir başka hata, kalabalık zemindir. Desenli arka plan, harfleri yutar.</p>\n<p>Üçüncü hata, çok küçük metindir. Telefonda okunamayan yazı, işe yaramaz.</p>\n<h2 id=\"contrast-and-filters\">Kontrast, filtreler ve metin bir arada</h2>\n<p>Filtreler, kontrastı değiştirir. Filtre uyguladıktan sonra metni yeniden kontrol edin.</p>\n<p>Filtre, fotoğrafı koyulaştırabilir. Beyaz yazı, filtre sonrası daha okunur olabilir.</p>\n<p>Önce filtreyi uygulayın, sonra metni ekleyin. Sıralama, doğru sonucu verir.</p>\n<h2 id=\"before-after-examples\">Önce ve sonra: iyi kontrast nasıl görünür?</h2>\n<p>Önce: beyaz yazı, açık fotoğrafta kaybolur. Sonra: koyu panel eklenir, yazı okunur.</p>\n<p>Önce: küçük siyah yazı, koyu zeminde kaybolur. Sonra: yazı büyütülür ve beyaz yapılır.</p>\n<p>Karşılaştırma, farkı gösterir. İyi kontrast, anında belli olur.</p>\n<h2 id=\"readability-checklist\">Yayınlamadan önce okunabilirlik listesi</h2>\n<p>Yazıyla zemin arasındaki farkı gözünüzle ölçün; fark küçükse kontrastı artırın, yoksa metin zemine karışır.</p>\n<p>Kontrast ayarı bittiğinde yazıyı telefon ekranında açın; küçük ekranda kaybolan metin, masaüstünde iyi görünse bile başarısızdır.</p>\n<p>Yazı yüzlerin üstüne binmiyor, kontrast yeterli ve panel dengeliyse görsel yayına hazırdır.</p>\n<p>Özetle: kontrast önce gelir, yazı tipi sonra. Adımlar için <a href=\"/tr/blog/gorsele-metin-nasil-eklenir\">Görsele metin nasıl eklenir</a> yazısına bakın; kontrast ayarı için <a href=\"/tr/blog/gorsel-kontrasti-nasil-ayarlanir\">görsel kontrastı nasıl ayarlanır</a> yazısı yardımcı olur. Kılavuzun tamamı <a href=\"/tr/blog/gorsel-kontrast-duzenleyici-rehberi\">kontrast düzenleyici kılavuzunda</a>; okunabilirlik için <a href=\"/tr/blog/gorsel-uzerindeki-metin-okunabilirlik-ipuclari\">görselde metin okunabilirliği ipuçları</a> hazırdır. Araçlar: <a href=\"/tr/gorsel-parlaklik-ayarla\">parlaklık düzenleyici</a> ve <a href=\"/tr/gorsel-kontrast-ayarla\">kontrast düzenleyici</a> sayfalarındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Açık bir fotoğrafta beyaz metni nasıl okunur yaparım?","answer":"Fotoğrafı koyulaştırın ya da metnin arkasına yarı saydam koyu panel koyun. Kontur da ekleyebilirsiniz; beyaz yazıya siyah kontur her zeminde görünür. Ya da metni fotoğrafın koyu alanına taşıyın."},{"question":"Tüm fotoğrafı mı yoksa yalnızca metnin arkasındaki alanı mı koyulaştırmalıyım?","answer":"Yalnızca metnin arkasındaki alanı koyulaştırın. Tüm fotoğrafı koyulaştırmak, görseli bozar. Degrade koyulaştırma ya da yarı saydam panel kullanın; fotoğrafın geri kalanı parlak kalır."},{"question":"Fotoğrafın üzerindeki metin için ne kadar kontrast gerekir?","answer":"Normal metin için 4.5:1, büyük metin için 3:1 kontrast oranı gerekir. Kontrastı göz kararı değil, araçla ölçün. Oran düşükse panel ekleyin ya da rengi değiştirin."},{"question":"Metnim bilgisayarımda iyi görünüyor ama telefonda neden okunamıyor?","answer":"Çünkü telefon ekranı küçüktür ve parlaklık farklıdır. Metni telefon boyutunda test edin; görseli küçültüp bakın. Küçük ekranda okunmayan metin, akışta işe yaramaz."},{"question":"Filtre, fotoğrafın üzerindeki metnin okunabilirliğini etkiler mi?","answer":"Evet. Filtre, kontrastı değiştirir; fotoğrafı koyulaştırabilir ya da açabilir. Önce filtreyi uygulayın, sonra metni ekleyin ve kontrastı yeniden kontrol edin."},{"question":"Yayınlamadan önce metin kontrastını nasıl test ederim?","answer":"Kontrast oranını ölçün, metni telefon boyutunda test edin ve başkalarına gösterin. Görseli küçültüp bakın; küçük resimde okunmayan metin akışta işe yaramaz. Dürüst geri bildirim alın."}];
